import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE: T, glbLoader, fontAtlas, primitives } = ctx;
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, Color, Box3 } = T;

  const root = new Group();
  root.userData.handlers = {};
  const cleanupFuncs = [];

  // 1. Backdrop plane: engineered gradient (using darkest base with midtone transition)
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({
    color: new Color(0x0b0b10),
    metalness: 0,
    roughness: 1,
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);
  cleanupFuncs.push(() => {
    backdropGeo.dispose();
    backdropMat.dispose();
  });

  // 2. Cylindrical plinth: radius 1.4, height 0.25, top at y = -1.1
  const plinthGeo = new CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new MeshStandardNodeMaterial({
    color: new Color(0x14141a),
    metalness: 0.3,
    roughness: 0.7,
  });
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.1 + 0.125; // Center of cylinder
  root.add(plinth);
  cleanupFuncs.push(() => {
    plinthGeo.dispose();
    plinthMat.dispose();
  });

  // 3. Contact shadow: radial gradient approximation under plinth
  const shadowGeo = new PlaneGeometry(3.2, 3.2); // 1.6 radius × 2
  const shadowMat = new MeshStandardNodeMaterial({
    color: new Color(0x000000),
    transparent: true,
    opacity: 0.55,
    metalness: 0,
    roughness: 1,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -1.125;
  shadow.position.z = 0.05;
  root.add(shadow);
  cleanupFuncs.push(() => {
    shadowGeo.dispose();
    shadowMat.dispose();
  });

  // 4. Load watch mesh and normalize
  glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const watchMesh = gltf.scene;

    // Normalize to 2.2 units tall, centered at origin
    const bbox = new Box3().setFromObject(watchMesh);
    const currentHeight = bbox.max.y - bbox.min.y;
    const scaleFactor = 2.2 / Math.max(currentHeight, 0.1);
    watchMesh.scale.multiplyScalar(scaleFactor);

    // Recompute bounds and center
    bbox.setFromObject(watchMesh);
    const centerY = (bbox.max.y + bbox.min.y) / 2;
    watchMesh.position.y -= centerY;

    // Apply brushed-metal PBR material to watch meshes
    watchMesh.traverse((node) => {
      if (node.isMesh) {
        const baseMat = node.material;
        const mat = new MeshPhysicalNodeMaterial({
          color: baseMat?.color || new Color(0xd0d0d0),
          metalness: 0.55,
          roughness: 0.52,
          clearcoat: 0.2,
          clearcoatRoughness: 0.4,
          // Note: anisotropy alignment to case tangent would require anisotropyMap
        });
        node.material = mat;
        cleanupFuncs.push(() => mat.dispose());
      }
    });

    root.add(watchMesh);
  });

  // 5. Key light: angled warm directional
  const keyLight = new T.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2.2, 1.4, 2.0);
  root.add(keyLight);

  // 6. Rim light: accent signal red, grazing the left flank
  const rimLight = new T.DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2.5, 1.0, -1.2);
  root.add(rimLight);

  // 7. Ambient fill
  const ambient = new T.AmbientLight(0xffffff, 0.2);
  root.add(ambient);

  // 8. Text: headline at y = -1.5, caption at y = -2.0 (0.5 units below)
  const headline = fontAtlas.createText('Calibre NA-01', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
  });
  headline.position.y = -1.5;
  headline.position.z = 0.5;
  root.add(headline);

  // Body text positioned between headline and caption
  const bodyText = fontAtlas.createText('Machined in-house. 41 mm. Grade 5 titanium.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'center',
  });
  bodyText.position.y = -1.82;
  bodyText.position.z = 0.5;
  root.add(bodyText);

  // Caption: 0.5 units below headline
  const caption = fontAtlas.createText('FROM 4200 USD / SHIPS IN 21 DAYS', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
  });
  caption.position.y = -2.0;
  caption.position.z = 0.5;
  root.add(caption);

  // 9. Cinematic primitives
  // Orbit on load: 0.15 rad/s, radius 0.6
  const orbitResult = primitives.orbit(root, { speed: 0.15, radius: 0.6 });
  if (orbitResult?.cleanup) cleanupFuncs.push(orbitResult.cleanup);

  // Depth-rotate on hover: up to 6 degrees
  const depthRotateResult = primitives['depth-rotate'](root, { maxDeg: 6 });
  if (depthRotateResult?.cleanup) cleanupFuncs.push(depthRotateResult.cleanup);

  // 10. Cleanup handler
  root.userData.cleanup = () => {
    cleanupFuncs.forEach(fn => {
      if (typeof fn === 'function') fn();
    });
  };

  return root;
}
